//! Original nonUID manual-position callback purpose. Private UserEntry reply
//! must resolve the current opaque P2P span UID; scalar/UID-local DATA cannot.
use super::*;
use ring::digest::{Context,SHA256};
struct ResolutionEntry{fingerprint:[u8;32],active:bool}
pub(super) struct ReadStatusResolutionBook{retired:AtomicBool,entries:Mutex<BTreeMap<String,ResolutionEntry>>}
impl ReadStatusResolutionBook{pub(super) fn original()->Arc<Self>{Arc::new(Self{retired:AtomicBool::new(false),entries:Mutex::new(BTreeMap::new())})}pub(super) fn retire(&self){self.retired.store(true,Ordering::SeqCst);}}
impl Drop for ReadStatusResolutionBook{fn drop(&mut self){let entries=self.entries.get_mut().unwrap_or_else(|e|e.into_inner());for(mut nonce,_)in std::mem::take(entries){zeroize::Zeroize::zeroize(&mut nonce);}}}
pub(in super::super::super) struct ReadStatusResolutionGuard{book:Arc<ReadStatusResolutionBook>,nonce:Zeroizing<String>,fingerprint:[u8;32]}
impl Drop for ReadStatusResolutionGuard{fn drop(&mut self){let mut entries=lock(&self.book.entries);if let Some(entry)=entries.get_mut(self.nonce.as_str()){if entry.fingerprint==self.fingerprint{entry.active=false;}}}}
impl ReadStatusAction{
    pub(in super::super::super) fn claim_recipient_resolution(&self)->Result<ReadStatusResolutionGuard,&'static str>{if !self.live(){return Err(STATUS_SCOPE);}let book=self.target._reservation.resources.resolutions.clone();if book.retired.load(Ordering::SeqCst){return Err(STATUS_SCOPE);}let context=self.target.span.receipt_context();let(box_id,index,span_hash)=self.target.span.receipt_span();let mut h=Context::new(&SHA256);h.update(b"original-manual-recipient-inflight-v1\0");for part in [self.run.line_id().as_bytes(),self.run.nonce().as_bytes(),context.binding.receipt_epoch().as_bytes(),box_id]{h.update(&(part.len()as u64).to_be_bytes());h.update(part);}h.update(&self.target.id.to_be_bytes());h.update(&self.run.revision().to_be_bytes());h.update(&index.to_be_bytes());h.update(&span_hash);if let Some(hash)=self.recipient_hash(){h.update(&[1]);h.update(&hash);}else{h.update(&[0]);}let mut fingerprint=[0;32];fingerprint.copy_from_slice(h.finish().as_ref());let mut entries=lock(&book.entries);
        if let Some(entry)=entries.get(self.nonce.as_str()){if entry.fingerprint!=fingerprint{return Err("app_account_im_read_status_nonce_conflict");}return Err(if entry.active{"app_account_im_read_status_resolution_inflight"}else{"app_account_im_read_status_resolution_finished"});}if entries.len()>=MAX_LOCAL as usize{return Err("app_account_im_read_status_recipient_capacity");}if !self.live()||book.retired.load(Ordering::SeqCst){return Err(STATUS_SCOPE);}entries.insert(self.nonce.to_string(),ResolutionEntry{fingerprint,active:true});drop(entries);Ok(ReadStatusResolutionGuard{book,nonce:self.nonce.clone(),fingerprint})}
    pub(in super::super::super) fn recipient_action(&self)->Option<Arc<UserEntryAction>>{self.recipient_action.clone()}
    pub(super) fn recipient_hash(&self)->Option<[u8;32]>{self.recipient.as_ref().map(|uri|{let mut h=Context::new(&SHA256);h.update(b"original-im-read-status-recipient-v1\0");h.update(&(uri.len()as u64).to_be_bytes());h.update(uri);let mut out=[0;32];out.copy_from_slice(h.finish().as_ref());out})}
    pub(in super::super::super) fn confirm_recipient(&self,reply:OwnedUserEntryReply)->Result<(),&'static str>{let action=self.recipient_action.as_ref().ok_or(STATUS_SCOPE)?;if !self.live()||reply.resolved_uid_for(action)!=Some(&self.target.span.box_bytes()[4..]){return Err("app_account_im_read_status_recipient_unconfirmed");}
        self.database.with_conn(|conn|{let tx=Transaction::new_unchecked(conn,TransactionBehavior::Deferred).map_err(|_|STORAGE)?;self.target.span.receipt_context().validate(&tx)?;self.target.validate_current(&tx)?;self.same_nonce(&tx)?;if !self.live(){return Err(STATUS_SCOPE);}tx.commit().map_err(|_|STORAGE)}) .map_err(|e|if e==SCOPE||e==STATUS_SCOPE{"app_account_im_read_status_recipient_target_stale"}else{e})?;
        let mut current=lock(&self.recipient_reply);if current.is_some(){return Err(STATUS_SCOPE);}*current=Some(Arc::new(reply));drop(current);self.require_recipient()
    }
    pub(super) fn require_recipient(&self)->Result<(),&'static str>{if self.recipient.is_none(){return Ok(());}let action=self.recipient_action.as_ref().ok_or(STATUS_SCOPE)?;if !self.live()||!lock(&self.recipient_reply).as_ref().is_some_and(|r|r.resolved_uid_for(action)==Some(&self.target.span.box_bytes()[4..])){return Err("app_account_im_read_status_recipient_unconfirmed");}Ok(())}
    pub(super) fn same_nonce(&self,conn:&Connection)->Result<Option<ReadStatusView>,&'static str>{let context=self.target.span.receipt_context();let(box_id,index,span_hash)=self.target.span.receipt_span();let old:Option<(i64,i64,i64,Vec<u8>,i64,Vec<u8>,Vec<u8>,String,String,Option<Vec<u8>>)>=conn.query_row("SELECT id,target_id,revision,identity_key,target_index,span_hash,box_id,run_nonce,scope_epoch,recipient_hash FROM app_voice_im_read_status_actions WHERE line_id=?1 AND user_nonce=?2",params![self.run.line_id(),self.nonce.as_str()],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?,r.get(4)?,r.get(5)?,r.get(6)?,r.get(7)?,r.get(8)?,r.get(9)?))).optional().map_err(|_|STORAGE)?;
        if let Some((id,target_id,revision,identity,saved_index,saved_hash,saved_box,saved_run,saved_epoch,saved_recipient))=old{let recipient_hash=self.recipient_hash();if target_id!=self.target.id||revision!=self.run.revision()as i64||identity.as_slice()!=context.binding.identity().as_slice()||saved_index!=index||saved_hash.as_slice()!=span_hash.as_slice()||saved_box.as_slice()!=box_id||saved_run!=self.run.nonce()||saved_epoch!=context.binding.receipt_epoch()||saved_recipient.as_deref()!=recipient_hash.as_ref().map(|h|h.as_slice()){return Err("app_account_im_read_status_nonce_conflict");}return Ok(Some(view(conn,id)?));}Ok(None)
    }
    pub(in super::super::super) fn recipient_preflight(&self)->Result<Option<ReadStatusView>,&'static str>{self.database.with_conn(|conn|{let tx=Transaction::new_unchecked(conn,TransactionBehavior::Deferred).map_err(|_|STORAGE)?;if !self.live(){return Err(STATUS_SCOPE);}let context=self.target.span.receipt_context();context.validate(&tx)?;self.target.validate_current(&tx)?;if let Some(v)=self.same_nonce(&tx)?{tx.commit().map_err(|_|STORAGE)?;return Ok(Some(v));}
        let(box_id,_,_)=self.target.span.receipt_span();let unknown:bool=tx.query_row("SELECT EXISTS(SELECT 1 FROM app_voice_im_read_status_actions WHERE line_id=?1 AND identity_key=?2 AND box_id=?3 AND state=0) OR EXISTS(SELECT 1 FROM app_voice_im_read_receipts WHERE line_id=?1 AND identity_key=?2 AND box_id=?3 AND state=0)",params![self.run.line_id(),context.binding.identity().as_slice(),box_id],|r|r.get(0)).map_err(|_|STORAGE)?;if unknown{return Err("app_account_im_receipt_uncertain");}let(local,total):(i64,i64)=tx.query_row("SELECT COALESCE(SUM(line_id=?1),0),COUNT(*) FROM app_voice_im_read_status_actions",[self.run.line_id()],|r|Ok((r.get(0)?,r.get(1)?))).map_err(|_|STORAGE)?;if local>=MAX_LOCAL||total>=MAX_GLOBAL{return Err(FULL);}if !self.live(){return Err(STATUS_SCOPE);}tx.commit().map_err(|_|STORAGE)?;Ok(None)}) .map_err(|e|if self.recipient.is_some()&&(e==SCOPE||e==STATUS_SCOPE){"app_account_im_read_status_recipient_target_stale"}else{e})}
}
